enc() { printf '%s' "$1" | /usr/bin/od -An -tx1 -v | /usr/bin/tr ' ' '\n' | /usr/bin/grep . | /usr/bin/sed 's/^/%/' | /usr/bin/tr -d '\n'; }
app=$(/usr/bin/lsappinfo info -only name "$OPENCLIP_BUNDLE_ID" 2>/dev/null | /usr/bin/sed -n 's/.*"LSDisplayName"="\(.*\)".*/\1/p')
/usr/bin/open -g "leafy://lookup?mode=define&text=$(enc "$OPENCLIP_TEXT")&app=$(enc "$app")" 2>/dev/null || printf '{"type":"toast","message":"Leafy is not installed","style":"error"}'

